<?php
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/admin-layout.php';require_role(['admin','super_admin']);$user=current_user();$statuses=['not_contacted'=>'Not contacted','contacted'=>'Contacted','not_qualified'=>'Not qualified','qualified'=>'Qualified','applied'=>'Applied'];$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'inquiry_id',FILTER_VALIDATE_INT);$status=trim((string)($_POST['status']??''));if(!verify_csrf($_POST['_csrf']??''))$error='Your session expired. Refresh and try again.';elseif(!$id||!isset($statuses[$status]))$error='Choose a valid inquiry and status.';else{$stmt=$pdo->prepare('UPDATE inquiries SET status=?,updated_at=NOW() WHERE id=?');$stmt->execute([$status,$id]);$notice=$stmt->rowCount()?'Inquiry status updated.':'No inquiry was changed.';}}
$query=trim((string)($_GET['q']??''));$filter=trim((string)($_GET['status']??''));$where=[];$params=[];if($query!==''){$where[]='(full_name LIKE ? OR email LIKE ? OR phone LIKE ? OR country LIKE ?)';$term='%'.$query.'%';array_push($params,$term,$term,$term,$term);}if(isset($statuses[$filter])){$where[]='status=?';$params[]=$filter;}$sql='SELECT * FROM inquiries'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC LIMIT 300';$stmt=$pdo->prepare($sql);$stmt->execute($params);$inquiries=$stmt->fetchAll();$counts=array_fill_keys(array_keys($statuses),0);foreach($pdo->query('SELECT status,COUNT(*) total FROM inquiries GROUP BY status')->fetchAll() as $row)if(isset($counts[$row['status']]))$counts[$row['status']]=(int)$row['total'];
?><!doctype html><html lang="en"><head><?php require_once dirname(__DIR__, 2) . '/includes/analytics.php'; ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Inquiries | Medcon Admin</title><link rel="stylesheet" href="<?=esc(app_url('assets/css/app.css'))?>"></head><body class="medcon-app mc-role-body"><?php admin_portal_header($user,'inquiries');?><main class="mc-role-main"><div class="mc-portal-heading"><div><span class="mc-kicker">Customer enquiries</span><h1>Inquiries</h1><p>Homepage, Apply, Contact, and WhatsApp-continuation submissions in one place.</p></div></div><?php if($notice):?><div class="mc-success" role="status"><?=esc($notice)?></div><?php endif;?><?php if($error):?><div class="mc-errors" role="alert"><?=esc($error)?></div><?php endif;?><section class="mc-panel"><div class="mc-section-head"><div><h2>All inquiries</h2><p><?=array_sum($counts)?> total · <?=$counts['not_contacted']?> awaiting contact</p></div><form method="get" class="mc-review-form" style="grid-template-columns:minmax(180px,1fr) 170px auto;display:grid"><input type="search" name="q" value="<?=esc($query)?>" placeholder="Search name, email or phone"><select name="status"><option value="">All statuses</option><?php foreach($statuses as $value=>$label):?><option value="<?=esc($value)?>"<?=$filter===$value?' selected':''?>><?=esc($label)?></option><?php endforeach;?></select><button class="mc-btn-secondary">Filter</button></form></div><div class="mc-table-wrap" style="margin-top:24px"><table><thead><tr><th>Customer</th><th>Type</th><th>Study details</th><th>Source</th><th>Message</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php if(!$inquiries):?><tr><td colspan="7">No inquiries found.</td></tr><?php else:foreach($inquiries as $inquiry):?><tr><td><strong><?=esc($inquiry['full_name'])?></strong><br><a href="mailto:<?=esc($inquiry['email'])?>"><?=esc($inquiry['email'])?></a><br><a href="tel:<?=esc($inquiry['phone'])?>"><?=esc($inquiry['phone'])?></a><br><small><?=esc($inquiry['country'])?></small></td><td><?=esc(ucfirst($inquiry['person_type']))?></td><td><?=esc($inquiry['education_level'])?><br><small><?=esc($inquiry['preferred_programme']?:'Programme not selected')?> · <?=esc($inquiry['preferred_college']?:'College not selected')?><br><?=esc($inquiry['intended_intake'])?></small></td><td><?=esc(ucfirst($inquiry['source_page']))?><br><small><?=esc(ucfirst($inquiry['submission_channel']))?></small></td><td><?=nl2br(esc($inquiry['message']?:'—'))?></td><td><form method="post" class="mc-review-form"><?=csrf_field()?><input type="hidden" name="inquiry_id" value="<?=(int)$inquiry['id']?>"><select name="status" aria-label="Status for <?=esc($inquiry['full_name'])?>"><?php foreach($statuses as $value=>$label):?><option value="<?=esc($value)?>"<?=$inquiry['status']===$value?' selected':''?>><?=esc($label)?></option><?php endforeach;?></select><button class="mc-btn-secondary">Update</button></form></td><td><?=esc(date('j M Y, g:i a',strtotime($inquiry['created_at'])))?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main><?php admin_portal_footer();?></body></html>
